CREATE DEFINER=`root`@`localhost` PROCEDURE `generate_customers` ()   BEGIN
  DECLARE i INT DEFAULT 1;
  DECLARE selected_plan ENUM('Basic','Standard','Premium');
  DECLARE rate DECIMAL(10,2);

