      CONCAT('Lastname', i),
      DATE_SUB(CURDATE(), INTERVAL FLOOR(RAND(i)*12000) DAY),
      ELT(FLOOR(1 + RAND(i*2)*3), 'Male','Female','Other'),
      CONCAT('09', FLOOR(100000000 + RAND(i*3)*899999999)),
      CONCAT('customer', i, '@gmail.com'),
      MD5(CONCAT('password', i)),
      'Barangay IV, Daet, Camarines Norte',
      CASE
        WHEN RAND(i*4) < 0.5 THEN
          CONCAT(
            ELT(
              FLOOR(1 + RAND(i*5)*20),
              'Bagasbas','Barangay I','Barangay II','Barangay III','Barangay IV',
              'Barangay V','Barangay VI','Barangay VII','Barangay VIII','Barangay IX',
              'Barangay X','Camambugan','Cobangbang','Dogongan','Gahonon',
              'Lag-on','Magang','Mancruz','Pamorangon','San Isidro'
            ),
            ', Daet, Camarines Norte'
          )
        ELSE
          CONCAT(
            ELT(
              FLOOR(1 + RAND(i*6)*14),
              'Cayucyucan','Colasi','Gaboc','Hamorawon','Hinipaan','Lanot',
              'Mambungalon','Manguisoc','Masalongsalong','Pambuhan',
              'San Roque','Tarum','Catandunganon','Del Rosario'
            ),
            ', Mercedes, Camarines Norte'
          )
      END,
      ELT(
        FLOOR(1 + RAND(i*10)*10),
        'Near Barangay Hall',
        'Near Public Market',
        'Across Elementary School',
        'Behind Chapel',
        'Beside Covered Court',
        'In front of the Municipal Hall',
        'Near Barangay Outpost',
        'Beside Sari-Sari Store',
