CREATE DEFINER=`root`@`localhost` PROCEDURE `generate_inventory` ()   BEGIN
  DECLARE i INT DEFAULT 1;
  WHILE i <= 10000 DO
      item_name, brand, model_number, serial_number, item_type,
      unit_cost, selling_price, date_received, supplier_name,
      current_stock, reorder_level, item_location, status, staff_id
