CREATE DEFINER=`root`@`localhost` PROCEDURE `generate_payments` ()   BEGIN
  DECLARE i INT DEFAULT 1;
  DECLARE cust_id INT;
  DECLARE staff_id INT;
  DECLARE svc_id INT;
  DECLARE billing_choice ENUM('plan_type','service_type');
  DECLARE install_date DATE;
  DECLARE svc_date DATE;
  DECLARE svc_cost DECIMAL(10,2);

  WHILE i <= 10000 DO
    SET cust_id = FLOOR(1 + RAND(i*1)*10000);
    SET staff_id = FLOOR(1 + RAND(i*2)*10000);
    SET billing_choice = ELT(FLOOR(1 + RAND(i*3)*2), 'plan_type','service_type');

    SELECT date_installed INTO install_date FROM customer WHERE customer_id = cust_id;

    IF billing_choice = 'plan_type' THEN
        customer_id, staff_id, billing_type, date_of_payment, payment_method
      )
      VALUES (
        cust_id,
        staff_id,
        billing_choice,
        IF(
          RAND(i*4) < 0.7,
          DATE_ADD(install_date, INTERVAL FLOOR(RAND(i*5)*35) DAY),
          NULL
        ),
        ELT(FLOOR(1 + RAND(i*8)*2), 'walk_in','gcash')
      );
    ELSE
      SELECT service_id, date_completed, service_cost
      INTO svc_id, svc_date, svc_cost
      FROM service
      WHERE customer_id = cust_id
      ORDER BY RAND()
      LIMIT 1;

      IF svc_id IS NOT NULL THEN
          customer_id, staff_id, service_id, billing_type, date_of_payment, payment_method
        )
        VALUES (
          cust_id,
          staff_id,
          svc_id,
          billing_choice,
          IF(
            RAND(i*6) < 0.7,
            DATE_ADD(svc_date, INTERVAL FLOOR(RAND(i*7)*10) DAY),
            NULL
          ),
          ELT(FLOOR(1 + RAND(i*9)*2), 'walk_in','gcash')
        );
      END IF;
    END IF;

    SET i = i + 1;
  END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `generate_service` ()   BEGIN
  DECLARE i INT DEFAULT 1;
  DECLARE cust_id INT;
  DECLARE staff_id INT;
  DECLARE item_id INT;
  DECLARE install_date DATE;

  WHILE i <= 10000 DO
    SET cust_id = FLOOR(1 + RAND()*10000);
    SET staff_id = FLOOR(1 + RAND()*10000);
    SET item_id = FLOOR(1 + RAND()*10000);

    SELECT date_installed INTO install_date FROM customer WHERE customer_id = cust_id;
    IF install_date IS NULL THEN
      SET install_date = CURDATE();
    END IF;

      customer_id, staff_id, item_id, service_type,
      date_requested, time_requested, date_completed,
      service_description, notes, status, service_cost,
      payment_method, technician_notes, customer_rating
    )
    VALUES (
      cust_id,
      staff_id,
      item_id,
      ELT(FLOOR(1 + (RAND()*3)), 'Installation','Repair','Relocation'),
      DATE_ADD(install_date, INTERVAL FLOOR(RAND()*90) DAY),
      SEC_TO_TIME(FLOOR(RAND()*86400)),
      DATE_ADD(install_date, INTERVAL FLOOR(RAND()*97) DAY),
      CONCAT('Service details #', i),
      ELT(
        FLOOR(1 + (RAND()*3)),
        'Customer requested assistance',
        'Technician follow-up required',
        'Routine maintenance'
      ),
      ELT(FLOOR(1 + (RAND()*3)), 'Requested','In Progress','Completed'),
      ROUND(500 + RAND()*1500, 2),
      ELT(FLOOR(1 + (RAND()*2)), 'walk_in','gcash'),
      CONCAT('Technician notes for service ', i),
      FLOOR(1 + (RAND()*10))
    );

    SET i = i + 1;
  END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `generate_staff` ()   BEGIN
  DECLARE i INT DEFAULT 1;
  DECLARE pos ENUM('Technician','Customer Service','Inventory');
  DECLARE rate DECIMAL(10,2);
  DECLARE access ENUM('Admin','Customer Service');

  WHILE i <= 10000 DO
    SET pos = ELT(FLOOR(1 + RAND(i*5)*3), 'Technician','Customer Service','Inventory');
    SET rate = CASE
      WHEN pos = 'Technician' THEN 500.00
      WHEN pos IN ('Customer Service','Inventory') THEN 365.00
    END;
    SET access = CASE
      WHEN pos = 'Inventory' THEN 'Admin'
      WHEN pos = 'Customer Service' THEN 'Customer Service'
      ELSE NULL
    END;

      first_name, last_name, birthdate, sex, contact_number,
      email_address, address, position, date_hired,
      username, password_hash, access_level, department, daily_rate
    )
    VALUES (
      CONCAT('Staff', i),
      CONCAT('Lastname', i),
      DATE_SUB(CURDATE(), INTERVAL FLOOR(RAND(i)*10000) DAY),
      ELT(FLOOR(1 + RAND(i*2)*3), 'Male','Female','Other'),
      CONCAT('09', FLOOR(100000000 + RAND(i*3)*899999999)),
      CONCAT('staff', i, '@gmail.com'),
      CONCAT(ELT(FLOOR(1 + RAND(i*4)*2), 'Daet','Mercedes'), ', Camarines Norte'),
      pos,
      DATE_SUB(CURDATE(), INTERVAL FLOOR(RAND(i*6)*2000) DAY),
      CONCAT('user', i),
      MD5(CONCAT('pass', i)),
      access,
      ELT(FLOOR(1 + RAND(i*7)*3), 'Operations','Support','Billing'),
      rate
    );
    SET i = i + 1;
  END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `get_payment_by_page` (IN `page_num` INT)   BEGIN
  DECLARE offset_val INT;
  SET offset_val = (page_num - 1) * 25;

  SELECT *
  FROM payment
  ORDER BY date_of_payment DESC, payment_id DESC
  LIMIT 25 OFFSET offset_val;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `get_recent_customers` (IN `page_num` INT)   BEGIN
  DECLARE offset_val INT;
  SET offset_val = (page_num - 1) * 25;

  SELECT *
  FROM customer
  ORDER BY date_installed DESC, customer_id DESC
  LIMIT 25 OFFSET offset_val;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `get_staff_by_page` (IN `page_num` INT)   BEGIN
  DECLARE offset_val INT;
  SET offset_val = (page_num - 1) * 25;

  SELECT *
  FROM staff
  ORDER BY date_hired DESC, staff_id DESC
  LIMIT 25 OFFSET offset_val;
END$$

