DELIMITER $$
CREATE TRIGGER `set_monthly_rate` BEFORE INSERT ON `customer` FOR EACH ROW BEGIN
  IF NEW.plan_type = 'Basic' THEN
    SET NEW.monthly_rate = 700.00;
  ELSEIF NEW.plan_type = 'Standard' THEN
    SET NEW.monthly_rate = 1000.00;
  ELSEIF NEW.plan_type = 'Premium' THEN
    SET NEW.monthly_rate = 1500.00;
  END IF;

  IF NEW.billing_address IS NULL OR NEW.billing_address = '' THEN
    SET NEW.billing_address = 'Barangay IV, Daet, Camarines Norte';
  END IF;
END
$$
