CREATE TABLE `payment` (
  `payment_id` int(11) NOT NULL,
  `customer_id` int(11) NOT NULL,
  `staff_id` int(11) DEFAULT NULL,
  `service_id` int(11) DEFAULT NULL,
  `billing_type` enum('plan_type','service_type') NOT NULL,
  `monthly_rate` decimal(10,2) DEFAULT NULL,
  `amount_paid` decimal(10,2) DEFAULT NULL,
  `total_bill_amount` decimal(10,2) DEFAULT NULL,
  `date_of_payment` datetime DEFAULT NULL,
  `billing_start_datetime` datetime DEFAULT NULL,
  `billing_end_datetime` datetime DEFAULT NULL,
  `due_date` date DEFAULT NULL,
  `payment_method` enum('walk_in','gcash') DEFAULT 'walk_in',
  `status` enum('Paid','Unpaid') DEFAULT 'Unpaid',
  `notes` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `payment`
--


--
-- Triggers `payment`
--
DELIMITER $$
CREATE TRIGGER `before_payment_insert` BEFORE INSERT ON `payment` FOR EACH ROW BEGIN
  DECLARE plan VARCHAR(50);
  DECLARE rate DECIMAL(10,2);
  DECLARE install_date DATE;
  DECLARE svc_cost DECIMAL(10,2);
  DECLARE svc_date_completed DATE;

  SELECT plan_type, date_installed
  INTO plan, install_date
  FROM customer
  WHERE customer_id = NEW.customer_id;

  IF NEW.billing_type = 'service_type' AND NEW.service_id IS NOT NULL THEN
    SELECT service_cost, date_completed
    INTO svc_cost, svc_date_completed
    FROM service
    WHERE service_id = NEW.service_id;
  END IF;

  IF NEW.billing_type = 'plan_type' THEN
    SET rate = CASE
      WHEN plan = 'Basic' THEN 700.00
      WHEN plan = 'Standard' THEN 1000.00
      WHEN plan = 'Premium' THEN 1500.00
    END;
    SET NEW.monthly_rate = rate;
    SET NEW.amount_paid = rate;
    SET NEW.total_bill_amount = rate;
    SET NEW.due_date = DATE_ADD(install_date, INTERVAL 1 MONTH);
  ELSEIF NEW.billing_type = 'service_type' THEN
    SET NEW.amount_paid = svc_cost;
    SET NEW.total_bill_amount = svc_cost;
    SET NEW.due_date = svc_date_completed;
  END IF;

  SET NEW.billing_start_datetime = NEW.due_date;
  SET NEW.billing_end_datetime = NEW.due_date;

  IF NEW.date_of_payment IS NULL THEN
    SET NEW.status = 'Unpaid';
  ELSE
    IF NEW.date_of_payment > NEW.due_date THEN
      SET NEW.billing_start_datetime = NEW.date_of_payment;
      SET NEW.billing_end_datetime = NEW.date_of_payment;
    END IF;
    SET NEW.status = 'Paid';
  END IF;

  SET NEW.due_date = DATE(NEW.billing_end_datetime);
END
$$
DELIMITER ;

